r=requests.get(url,params={'db':'pubmed','term':q,'retmode':'json','retmax':20},timeout=30)
print('PUBMED',r.status_code,r.text[:2000])
for db in ['pubmed','pmc']:
    rr=requests.get(url,params={'db':db,'term':'syphilis rabbit infectivity test case report','retmode':'json','retmax':20},timeout=30)
    print(db,rr.text[:1000])
cr=requests.get('https://api.crossref.org/works',params={'query.title':'negative nontreponemal specific antitreponemal IgM active infectious syphilis','rows':10},timeout=30).json()
for x in cr['message']['items']:
    print('CROSSREF',x.get('title'),x.get('DOI'),x.get('published-print') or x.get('published-online'))
